package edu.riara.edp.week07;
import javafx.application.Application;import javafx.event.*;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class CustomEventDemo extends Application {public static class OrderEvent extends Event {public static final EventType<OrderEvent> SUBMITTED=new EventType<>(Event.ANY,"SUBMITTED");public final String item;public OrderEvent(String item){super(SUBMITTED);this.item=item;}}public void start(Stage s){TextField input=new TextField("Laptop");Label output=new Label("Ready");Button submit=new Button("Send event");VBox root=new VBox(10,input,submit,output);root.addEventHandler(OrderEvent.SUBMITTED,e->output.setText("Ordered: "+e.item));submit.setOnAction(e->Event.fireEvent(root,new OrderEvent(input.getText())));s.setScene(new Scene(root,400,200));s.show();}public static void main(String[]a){launch(a);}}